using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(entity =>
        {
            entity.ToContainer("Sessions");

            // Fix 1: EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Existing documents already use "Discriminator", so explicitly preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 no longer embeds the discriminator in the JSON id property.
            // Existing documents have ids like "Session|abc-123". Preserve that format.
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Title { get; set; } = null!;
}

// Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
// All sync calls (ToList(), SaveChanges(), etc.) now throw.
// Convert to async equivalents:
//
//   BEFORE (throws in EF Core 9):
//     var sessions = db.Sessions.ToList();
//     db.SaveChanges();
//
//   AFTER:
//     var sessions = await db.Sessions.ToListAsync();
//     await db.SaveChangesAsync();

